const DISCOUNT_THRESHOLD_CENTS = 10000;
const DISCOUNT_RATE_NUM = 10; // percent

function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

/**
 * Creates a shopping cart backed by an injected storage adapter
 * (localStorage-shaped: getItem/setItem/removeItem).
 *
 * The whole cart persists as a single JSON document under `cart:v1`,
 * written on every mutation.
 */
export function createCart(storage) {
  if (!storage || typeof storage.getItem !== 'function' || typeof storage.setItem !== 'function') {
    throw new TypeError('createCart requires a storage with getItem/setItem');
  }

  // Rehydrate; corrupted JSON resets to an empty cart instead of throwing.
  let items = {};
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (raw != null) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        for (const [sku, line] of Object.entries(parsed)) {
          if (
            line &&
            typeof line === 'object' &&
            Number.isInteger(line.qty) &&
            line.qty > 0 &&
            Number.isInteger(line.unitPriceCents) &&
            line.unitPriceCents >= 0
          ) {
            items[sku] = { qty: line.qty, unitPriceCents: line.unitPriceCents };
          }
        }
      }
    }
  } catch {
    items = {};
    persist();
  }

  function serialize() {
    storage.setItem(STORAGE_KEY, JSON.stringify(items));
  }

  // Persist immediately after rehydration-reset so corruption doesn't recur.
  function persist() {
    serialize();
  }

  // Persist on every mutation (serialize is called by each mutator below).

  return {
    /** Add qty units of sku at unitPriceCents. Adds to an existing line. */
    add(sku, qty, unitPriceCents) {
      if (typeof sku !== 'string' || sku.length === 0) {
        throw new TypeError('add: sku must be a non-empty string');
      }
      if (!isValidQty(qty)) {
        throw new TypeError('add: qty must be a positive integer');
      }
      if (!Number.isInteger(unitPriceCents) || unitPriceCents < 0) {
        throw new TypeError('add: unitPriceCents must be a non-negative integer');
      }
      const existing = items[sku];
      items[sku] = {
        qty: (existing ? existing.qty : 0) + qty,
        unitPriceCents,
      };
      serialize();
    },

    /** Remove a line entirely. No-op if absent. */
    remove(sku) {
      delete items[sku];
      serialize();
    },

    /** Set quantity; qty of 0 removes the line. */
    setQty(sku, qty) {
      if (!Number.isInteger(qty) || qty < 0) {
        throw new TypeError('setQty: qty must be a non-negative integer');
      }
      if (qty === 0) {
        delete items[sku];
      } else if (items[sku]) {
        items[sku].qty = qty;
      } else {
        return; // nothing to set
      }
      serialize();
    },

    /**
     * Totals in integer cents. 10% discount when subtotal >= 10000 cents,
     * rounded to the nearest cent via integers only:
     * discountCents = floor((subtotal * 10 + 50) / 100)
     */
    totals() {
      let itemCount = 0;
      let subtotalCents = 0;
      for (const { qty, unitPriceCents } of Object.values(items)) {
        itemCount += qty;
        subtotalCents += qty * unitPriceCents;
      }
      const eligible = subtotalCents >= DISCOUNT_THRESHOLD_CENTS;
      // Round-half-up using pure integer math: (x*10 + 50) / 100 | 0
      const discountCents = eligible ? Math.floor((subtotalCents * DISCOUNT_RATE_NUM + 50) / 100) : 0;
      return {
        itemCount,
        subtotalCents,
        discountCents,
        totalCents: subtotalCents - discountCents,
      };
    },
  };
}

export { STORAGE_KEY };
