result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/cart/test/cart.test.js", "content": "import { describe, it, expect, vi } from 'vitest';
import { createCart, STORAGE_KEY } from '../src/cart.js';

/** localStorage-shaped in-memory stub with call tracking. */
function makeStorage() {
  const map = new Map();
  const calls = { setItem: [] };
  return {
    getItem: (k) => (map.has(k) ? map.get(k) : null),
    setItem: vi.fn((k, v) => {
      calls.setItem.push({ key: k, value: v });
      map.set(k, v);
    }),
    removeItem: (k) => map.delete(k),
    _map: map,
    _calls: calls,
  };
}

describe('createCart', () => {
  it('starts empty and writes on first mutation', () => {
    const storage = makeStorage();
    const cart = createCart(storage);

    expect(cart.totals()).toEqual({
      itemCount: 0,
      subtotalCents: 0,
      discountCents: 0,
      totalCents: 0,
    });

    cart.add('SKU-1', 2, 500);
    expect(storage.setItem).toHaveBeenCalledTimes(1);
    const written = JSON.parse(storage._map.get(STORAGE_KEY));
    expect(written).toEqual({ 'SKU-1': { qty: 2, unitPriceCents: 500 } });
  });

  it('persists after each operation', () => {
    const storage = makeStorage();
    const cart = createCart(storage);

    cart.add('A', 1, 300);
    expect(JSON.parse(storage.getItem(STORAGE_KEY))).toEqual({
      A: { qty: 1, unitPriceCents: 300 },
    });

    cart.add('A', 2, 300);
    expect(JSON.parse(storage.getItem(STORAGE_KEY))).toEqual({
      A: { qty: 3, unitPriceCents: 300 },
    });

    cart.setQty('A', 5);
    expect(JSON.parse(storage.getItem(STORAGE_KEY))['A'].qty).toBe(5);

    cart.remove('A');
    expect(JSON.parse(storage.getItem(STORAGE_KEY))).toEqual({});
  });

  it('setQty(sku, 0) removes the line', () => {
    const storage = makeStorage();
    const cart = createCart(storage);
    cart.add('A', 3, 100);
    cart.add('B', 1, 200);
    cart.setQty('A', 0);
    expect(JSON.parse(storage.getItem(STORAGE_KEY))).toEqual({
      B: { qty: 1, unitPriceCents: 200 },
    });
    expect(cart.totals().itemCount).toBe(1);
  });

  it('rehydrates into a second createCart instance', () => {
    const storage = makeStorage();
    const first = createCart(storage);
    first.add('WIDGET', 4, 2500); // 4 * 2500 = 10000 -> discount threshold
    first.add('GIZMO', 1, 999);

    const second = createCart(storage);
    expect(second.totals()).toEqual({
      itemCount: 5,
      subtotalCents: 10999,
      discountCents: 1100, // 10% of 10999 = 1099.9 -> rounds to 1100
      totalCents: 9899,
    });
  });

  it('resets to empty cart on corrupted stored JSON without throwing', () => {
    const storage = makeStorage();
    storage.setItem(STORAGE_KEY, '{not valid json!!');

    const cart = createCart(storage); // must not throw
    expect(cart.totals()).toEqual({
      itemCount: 0,
      subtotalCents: 0,
      discountCents: 0,
      totalCents: 0,
    });
    // Reset is persisted so the bad payload is gone
    expect(JSON.parse(storage.getItem(STORAGE_KEY))).toEqual({});

    // Cart is fully usable afterwards
    cart.add('A', 1, 100);
    expect(cart.totals().itemCount).toBe(1);
  });

  it('treats structurally invalid payloads (non-object/array) as corrupted', () => {
    for (const bad of ['"just a string"', '[1,2,3]', '42', 'null']) {
      const storage = makeStorage();
      storage.setItem(STORAGE_KEY, bad);
      const cart = createCart(storage);
      expect(cart.totals().itemCount).toBe(0);
    }
  });

  describe('discount rounding with integer cents', () => {
    it.each([
      // [subtotal construction, expectedDiscount]
      { lines: [['X', 1, 10000]], expectedSubtotal: 10000, expectedDiscount: 1000 }, // exactly at threshold
      { lines: [['X', 1, 9999]], expectedSubtotal: 9999, expectedDiscount: 0 }, // just below threshold
      { lines: [['X', 1, 10001]], expectedSubtotal: 10001, expectedDiscount: 1000 }, // .1 down -> 1000.1 -> 1000
      { lines: [['X', 1, 10005]], expectedSubtotal: 10005, expectedDiscount: 1001 }, // 1000.5 -> 1001 (half-up)
      { lines: [['X', 1, 10999]], expectedSubtotal: 10999, expectedDiscount: 1100 }, // 1099.9 -> 1100
      { lines: [['X', 1, 10199]], expectedSubtotal: 10199, expectedDiscount: 1020 }, // 1019.9 -> 1020
      { lines: [['X', 1, 10194]], expectedSubtotal: 10194, expectedDiscount: 1019 }, // 1019.4 -> 1019
    ])(
      'subtotal $expectedSubtotal -> discount $expectedDiscount',
      ({ lines, expectedSubtotal, expectedDiscount }) => {
        const cart = createCart(makeStorage());
        for (const [sku, qty, price] of lines) cart.add(sku, qty, price);
        const t = cart.totals();
        expect(t.subtotalCents).toBe(expectedSubtotal);
        expect(t.discountCents).toBe(expectedDiscount);
        expect(t.totalCents).toBe(expectedSubtotal - expectedDiscount);
        expect(Number.isInteger(t.discountCents)).toBe(true);
      }
    );
  });

  it('rejects invalid arguments', () => {
    const cart = createCart(makeStorage());
    expect(() => cart.add('', 1, 100)).toThrow(TypeError);
    expect(() => cart.add('A', 0, 100)).toThrow(TypeError);
    expect(() => cart.add('A', 1.5, 100)).toThrow(TypeError);
    expect(() => cart.add('A', 1, -1)).toThrow(TypeError);
    expect(() => cart.add('A', 1, 10.5)).toThrow(TypeError);
    expect(() => cart.setQty('A', -1)).toThrow(TypeError);
    expect(() => createCart(null)).toThrow(TypeError);
  });
});
"})
